arguments.new:
difference() {
  cylinder(r=outerR, h=H, $fn=180);
  ring_void_bot();
  ring_void_top();
  // center groove bore at root radius
  translate([0,0,Hb]) cylinder(r=rr_r, h=groove+0.2, $fn=180);
}

arguments.old:
difference() {
  cylinder(r=outerR, h=H, $fn=180);
  // half-pitch clocking: ring tooth enters planet gap
  rotate([0,0,180/Zr]) ring_void_bot();
  rotate([0,0,180/Zr]) ring_void_top();
  // center groove bore at root radius
  translate([0,0,Hb]) cylinder(r=rr_r, h=groove+0.2, $fn=180);
}
